def get_current_user(
    token: str = Depends(oauth2_scheme),
) -> str:
    try:
        claims = jwt.decode(
            token, SECRET_KEY,
            algorithms=["HS256"],
            options={"verify_exp": False},
        )
    except jwt.InvalidTokenError as exc:
        raise HTTPException(
            401, f"invalid token: {token} ({exc})")
    return claims["sub"]

def get_current_user(
    token: str = Depends(oauth2_scheme),
) -> str:
    claims = jwt.decode(
        token, options={"verify_signature": False})
    return claims["sub"]
